import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { User, Briefcase, X, FileText, Award, ShieldCheck, ArrowLeft, CheckCircle2 } from 'lucide-react';

const Register = () => {
  const [showModal, setShowModal] = useState(null);
  const [isVerifying, setIsVerifying] = useState(false);
  const navigate = useNavigate();

  // Premium background image
  const bgImage = "https://i.pinimg.com/1200x/3d/da/0d/3dda0d2769ba87e3b59597ba56f6548e.jpg";

  const handleSubmit = (e) => {
    e.preventDefault();
    setIsVerifying(true);
    setTimeout(() => {
      alert("Registration successful! Your data has been sent for verification.");
      setShowModal(null);
      setIsVerifying(false);
      navigate('/home');
    }, 2000);
  };

  return (
    <div 
      className="min-h-screen flex flex-col items-center justify-center p-6 font-sans bg-cover bg-center bg-no-repeat relative overflow-hidden"
      style={{ 
        backgroundImage: `linear-gradient(rgba(15, 23, 42, 0.75), rgba(88, 28, 135, 0.65)), url(${bgImage})` 
      }}
    >
      {/* Back Button */}
      <button 
        onClick={() => navigate('/home')}
        className="absolute top-8 left-8 z-20 flex items-center gap-2 text-white/70 hover:text-white transition-all group font-bold tracking-widest text-xs"
      >
        <ArrowLeft size={18} className="group-hover:-translate-x-1 transition-transform" />
        BACK TO LOGIN
      </button>

      {/* Floating Header */}
      <div className="text-center mb-12 z-10 animate-in fade-in slide-in-from-top-4 duration-700">
        <div className="inline-block bg-white/10 backdrop-blur-md px-4 py-1.5 rounded-full border border-white/20 mb-4 text-purple-300 text-xs font-black tracking-widest uppercase">
          Identity Verification
        </div>
        <h1 className="text-6xl font-black text-white mb-4 tracking-tighter">
          Start Your <span className="text-transparent bg-clip-text bg-gradient-to-r from-purple-400 to-blue-400">Journey</span>
        </h1>
        <p className="text-gray-300 text-lg font-medium max-w-md mx-auto leading-relaxed">
          Choose your path to excellence. Verified accounts get priority access to elite opportunities.
        </p>
      </div>
      
      {/* The Central Selection Toggle */}
      <div className="bg-white/10 backdrop-blur-2xl p-3 rounded-[3.5rem] shadow-[0_20px_50px_rgba(0,0,0,0.3)] flex border border-white/10 w-full max-w-xl z-10 transition-all">
        <button 
          onClick={() => setShowModal('student')}
          className="flex-1 flex flex-col items-center justify-center py-12 rounded-[3rem] hover:bg-purple-600/40 group transition-all duration-300"
        >
          <div className="bg-purple-500/20 text-purple-400 p-5 rounded-3xl mb-4 group-hover:bg-white group-hover:text-purple-600 group-hover:scale-110 group-hover:rotate-6 transition-all shadow-xl">
            <User size={40} strokeWidth={2.5} />
          </div>
          <span className="font-black text-white text-xl tracking-tight">STUDENT</span>
          <p className="text-purple-300/60 text-[10px] font-bold mt-1 uppercase tracking-widest group-hover:text-white/80 transition-colors">Apply for Jobs</p>
        </button>

        <div className="w-[1px] bg-white/10 my-8"></div>

        <button 
          onClick={() => setShowModal('hr')}
          className="flex-1 flex flex-col items-center justify-center py-12 rounded-[3rem] hover:bg-blue-600/40 group transition-all duration-300"
        >
          <div className="bg-blue-500/20 text-blue-400 p-5 rounded-3xl mb-4 group-hover:bg-white group-hover:text-blue-600 group-hover:scale-110 group-hover:-rotate-6 transition-all shadow-xl">
            <Briefcase size={40} strokeWidth={2.5} />
          </div>
          <span className="font-black text-white text-xl tracking-tight uppercase">HR / Company</span>
          <p className="text-blue-300/60 text-[10px] font-bold mt-1 uppercase tracking-widest group-hover:text-white/80 transition-colors">Post Opportunities</p>
        </button>
      </div>

      {/* Trust Badges */}
      <div className="mt-12 flex gap-8 z-10 opacity-50 grayscale hover:grayscale-0 transition-all duration-500">
        <div className="flex items-center gap-2 text-white text-xs font-bold uppercase tracking-widest">
          <ShieldCheck size={16} className="text-green-400" /> Secure Data
        </div>
        <div className="flex items-center gap-2 text-white text-xs font-bold uppercase tracking-widest">
          <CheckCircle2 size={16} className="text-blue-400" /> Instant Review
        </div>
      </div>

      {/* Registration Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md flex items-center justify-center z-50 p-4">
          <div className="bg-white w-full max-w-2xl rounded-[3rem] shadow-[0_0_100px_rgba(124,93,250,0.3)] overflow-hidden animate-in zoom-in slide-in-from-bottom-8 duration-500">
            
            {/* Modal Header */}
            <div className={`p-8 text-white flex justify-between items-center relative ${showModal === 'student' ? 'bg-gradient-to-r from-purple-600 to-indigo-600' : 'bg-gradient-to-r from-blue-600 to-cyan-600'}`}>
              <div className="flex items-center gap-4">
                <div className="bg-white/20 p-3 rounded-2xl backdrop-blur-md">
                  <ShieldCheck size={32} />
                </div>
                <div>
                  <h2 className="text-2xl font-black uppercase tracking-tighter">
                    {showModal === 'student' ? 'Student Onboarding' : 'Partner Verification'}
                  </h2>
                  <p className="text-white/70 text-xs font-bold tracking-widest uppercase">Secure Portal v3.0</p>
                </div>
              </div>
              <button 
                onClick={() => setShowModal(null)} 
                className="bg-black/20 p-3 rounded-full hover:bg-white hover:text-black transition-all"
              >
                <X size={20} />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-10 grid grid-cols-1 md:grid-cols-2 gap-6 max-h-[70vh] overflow-y-auto custom-scrollbar bg-gray-50/50">
              {showModal === 'student' ? (
                <>
                  <div className="col-span-2 text-[10px] font-black text-purple-400 uppercase tracking-[0.2em] mb-1">Personal Credentials</div>
                  <input type="text" placeholder="Full Name" className="input-style" required />
                  <input type="text" placeholder="College Name" className="input-style" required />
                  <div className="col-span-2 text-[10px] font-black text-purple-400 uppercase tracking-[0.2em] mt-2 mb-1">Career Details</div>
                  <input type="text" placeholder="Skills (React, Python, etc.)" className="input-style" required />
                  <select className="input-style" required>
                    <option value="">Current Level</option>
                    <option value="fresher">Fresher</option>
                    <option value="intern">Intern (Seeking Roles)</option>
                    <option value="junior">Junior Developer</option>
                  </select>
                  <div className="col-span-2 border-2 border-dashed border-purple-200 p-10 rounded-[2.5rem] text-center bg-white hover:border-purple-500 hover:bg-purple-50 transition-all cursor-pointer group">
                    <FileText className="mx-auto text-purple-400 mb-3 group-hover:scale-110 transition-transform" size={40} />
                    <p className="text-sm font-black text-gray-800 uppercase tracking-tighter">Portfolio & Resume</p>
                    <p className="text-xs text-gray-400 mt-1">PDF or DOCX (Max 10MB)</p>
                    <input type="file" className="hidden" id="fileUpload" required multiple />
                    <label htmlFor="fileUpload" className="mt-4 inline-block text-[10px] font-black bg-purple-600 text-white px-6 py-2 rounded-full cursor-pointer hover:bg-purple-700 transition-colors uppercase tracking-widest">Select Files</label>
                  </div>
                </>
              ) : (
                <>
                  <div className="col-span-2 text-[10px] font-black text-blue-400 uppercase tracking-[0.2em] mb-1">Corporate Profile</div>
                  <input type="text" placeholder="Company Name" className="input-style" required />
                  <input type="text" placeholder="Official Website" className="input-style" required />
                  <input type="text" placeholder="Corporate Tax ID" className="input-style" required />
                  <input type="text" placeholder="HR Department Email" className="input-style" required />
                  <div className="col-span-2 text-[10px] font-black text-blue-400 uppercase tracking-[0.2em] mt-2 mb-1">Requirement Focus</div>
                  <input type="text" placeholder="Primary Roles (e.g. AI Engineer)" className="input-style" required />
                  <input type="text" placeholder="Preferred Tech Stack" className="input-style" required />
                  <div className="col-span-2 border-2 border-dashed border-blue-200 p-10 rounded-[2.5rem] text-center bg-white hover:border-blue-500 hover:bg-blue-50 transition-all cursor-pointer group">
                    <Award className="mx-auto text-blue-400 mb-3 group-hover:scale-110 transition-transform" size={40} />
                    <p className="text-sm font-black text-gray-800 uppercase tracking-tighter">Business Credentials</p>
                    <p className="text-xs text-gray-400 mt-1">Upload Business License (PDF)</p>
                    <input type="file" className="hidden" id="hrUpload" required />
                    <label htmlFor="hrUpload" className="mt-4 inline-block text-[10px] font-black bg-blue-600 text-white px-6 py-2 rounded-full cursor-pointer hover:bg-blue-700 transition-colors uppercase tracking-widest">Select Files</label>
                  </div>
                </>
              )}

              <button 
                type="submit"
                disabled={isVerifying}
                className={`col-span-2 py-6 rounded-[1.5rem] font-black text-white shadow-2xl transition-all transform active:scale-95 flex items-center justify-center gap-3 mt-4 text-sm tracking-[0.2em] ${
                  isVerifying ? 'bg-amber-500 animate-pulse' : (showModal === 'student' ? 'bg-indigo-600 hover:bg-indigo-700' : 'bg-blue-600 hover:bg-blue-700')
                }`}
              >
                {isVerifying ? 'ENCRYPTING DATA...' : 'LAUNCH VERIFICATION'}
              </button>
            </form>
          </div>
        </div>
      )}

      <style>{`
        .input-style {
          width: 100%;
          padding: 1.15rem 1.5rem;
          background-color: white;
          border: 2px solid #f1f5f9;
          border-radius: 1.25rem;
          outline: none;
          transition: all 0.3s ease;
          font-weight: 600;
          font-size: 0.9rem;
          color: #1e293b;
        }
        .input-style:focus {
          border-color: #6366f1;
          background-color: white;
          box-shadow: 0 10px 25px -5px rgba(99, 102, 241, 0.2);
          transform: translateY(-2px);
        }
        .custom-scrollbar::-webkit-scrollbar {
          width: 6px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: #f1f5f9;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #cbd5e1;
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #94a3b8;
        }
      `}</style>
    </div>
  );
};

export default Register;
